-- ----------------------------
-- Table structure for mes_bom_outstock
-- ----------------------------
DROP TABLE IF EXISTS `mes_bom_outstock`;
CREATE TABLE `mes_bom_outstock`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `work_id` bigint(20) NOT NULL COMMENT '派单ID',
  `bom_id` bigint(20) NOT NULL COMMENT 'BOM版本ID',
  `bom_item_id` bigint(20) NOT NULL COMMENT 'BOM组件ID',
  `product_id` bigint(20) NOT NULL COMMENT '物料产品ID（组件对应的mes_product.id）',
  `process_route_id` bigint(20) NULL DEFAULT NULL COMMENT '工艺路线ID',
  `need_count` decimal(10, 2) NOT NULL COMMENT '需求数量（从BOM qty × 派单数量计算）',
  `out_count` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '已出库数量（累计）',
  `unit_id` bigint(20) NULL DEFAULT NULL COMMENT '单位ID',
  `batch_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批次号',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态（0=待出库，1=部分出库，2=出库完成）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '租户ID',
  `create_dept` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_work_bom`(`work_id`, `bom_id`, `bom_item_id`) USING BTREE,
  INDEX `idx_product`(`product_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_batch_no`(`batch_no`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'BOM组件出库管理表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of mes_bom_outstock
-- ----------------------------

