-- ----------------------------
-- Table structure for mes_inventory_ledger
-- ----------------------------
DROP TABLE IF EXISTS `mes_inventory_ledger`;
CREATE TABLE `mes_inventory_ledger`  (
  `id` bigint(20) NULL DEFAULT NULL COMMENT '编号',
  `sn` int(10) NOT NULL AUTO_INCREMENT,
  `stockid` bigint(20) NOT NULL COMMENT '物料',
  `location_id` bigint(20) NULL DEFAULT NULL COMMENT '库位ID（FK',
  `quantity` int(10) NOT NULL COMMENT '操作数量（正数入库，负数出库）',
  `operation` tinyint(3) NOT NULL COMMENT '操作类型（1入库/2出库）',
  `batch_no` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '业务批次号',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '角色状态（1正常 2进行中 3已完成 0异常完工,4待检查）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '000000' COMMENT '租户编号',
  PRIMARY KEY (`sn`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '库存流水表\n' ROW_FORMAT = DYNAMIC;

