  `pid` bigint(20) NULL DEFAULT 0 COMMENT '组成件',
  `stock_id` bigint(20) NULL DEFAULT NULL COMMENT '库存单位',
  `stock` decimal(15, 6) NULL DEFAULT 0.000000 COMMENT '库存量',
  `ver` int(10) NULL DEFAULT NULL COMMENT '版本',
  `weight` decimal(10, 6) NULL DEFAULT NULL COMMENT '重量',
  `need_count` decimal(20, 6) NULL DEFAULT NULL COMMENT '需求数量',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '角色状态（0正常 1停用）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '000000' COMMENT '租户编号',
  `mustbe` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否自制件',
  `quacount` int(11) NULL DEFAULT 0 COMMENT '质检次数',
  `stocks` bigint(20) NULL DEFAULT NULL COMMENT '库存',
  `process_route_id` bigint(20) NULL DEFAULT NULL COMMENT '关联的工艺路线ID',
  `imgs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '图纸',
  `colors` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '颜色',
  `stime` decimal(10, 4) NULL DEFAULT NULL COMMENT '工时',
  `prices` decimal(10, 4) NULL DEFAULT NULL COMMENT '工费',
  `stl` tinyint(3) NULL DEFAULT 1 COMMENT 'bom算法',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '产品管理' ROW_FORMAT = DYNAMIC;

