-- ----------------------------
-- Table structure for mes_stock
-- ----------------------------
DROP TABLE IF EXISTS `mes_stock`;
CREATE TABLE `mes_stock`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tilte` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '名称',
  `warnnum` decimal(10, 4) NULL DEFAULT 0.0000 COMMENT '报警',
  `type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '完成度',
  `otype` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品类',
  `iid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图号',
  `sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库存编码',
  `custid` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '供应商',
  `stockid` bigint(20) NULL DEFAULT NULL COMMENT '库存信息',
  `instock` decimal(15, 6) NULL DEFAULT 0.000000 COMMENT '总入库',
  `outstock` decimal(10, 6) NULL DEFAULT 0.000000 COMMENT '总出库',
  `nowstock` decimal(15, 6) NULL DEFAULT NULL COMMENT '当前库存',
  `unitid` bigint(20) NULL DEFAULT NULL COMMENT '单位',
  `gk` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格',
  `proid` bigint(20) NULL DEFAULT NULL COMMENT '物料',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '角色状态（0正常 1停用）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `pcount` int(11) NULL DEFAULT 0 COMMENT '入库批次',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '000000' COMMENT '租户编号',
  `pricein` decimal(10, 4) NULL DEFAULT 0.0000 COMMENT '进货价',
  `pricesale` decimal(10, 4) NULL DEFAULT 0.0000 COMMENT '销售价',
  `sales` tinyint(3) NULL DEFAULT 0 COMMENT '收否售卖',
  `capacity` decimal(10, 2) NULL DEFAULT NULL COMMENT '产能（单位时间产量）',
  `prices` decimal(10, 2) NULL DEFAULT NULL COMMENT '工费',
  `image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料图片URL',
  `kwrec` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '历史库位 ',
  `ptype` bigint(20) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '仓库信息' ROW_FORMAT = DYNAMIC;

