-- Records of mes_stocktaking
-- ----------------------------

-- ----------------------------
-- Table structure for mes_task
-- ----------------------------
DROP TABLE IF EXISTS `mes_task`;
CREATE TABLE `mes_task`  (
  `id` bigint(20) NOT NULL COMMENT 'id',
  `sn` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '流转批次号',
  `pro_id` bigint(20) NULL DEFAULT NULL COMMENT '产品',
  `workplace_id` bigint(20) NULL DEFAULT NULL COMMENT '工作站',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户',
  `needcount` int(11) NULL DEFAULT NULL COMMENT '所需数量',
  `original_needcount` bigint(20) NULL DEFAULT NULL COMMENT '原始需求数量（记录主任务被拆分前的总数量）',
  `markcount` int(11) NULL DEFAULT NULL COMMENT '生产数量',
  `okprocess` int(11) NULL DEFAULT 0 COMMENT '完成工序',
  `scrapcount` int(11) NULL DEFAULT NULL COMMENT '报废数量',
  `is_check` int(11) NULL DEFAULT 0 COMMENT '全部质检次数',
  `currproid` bigint(20) NULL DEFAULT NULL COMMENT '流程id',
  `currprocess` int(11) NULL DEFAULT NULL COMMENT '当前流程',
  `allprocess` int(11) NULL DEFAULT NULL COMMENT '所有工序',
  `redoingcount` int(11) NULL DEFAULT NULL COMMENT '返工数量',
  `redoingid` bigint(20) NULL DEFAULT NULL COMMENT '返工id',
  `is_top` tinyint(3) NULL DEFAULT NULL COMMENT '是否加急',
  `work_id` bigint(20) NULL DEFAULT NULL COMMENT '主表id',
  `process_route_id` bigint(20) NULL DEFAULT NULL COMMENT '关联的工艺路线ID（process_route.id）',
  `step_id` bigint(20) NULL DEFAULT NULL COMMENT '关联的工序步骤ID（process_step.id）',
  `branch_id` bigint(20) NULL DEFAULT NULL COMMENT '分支主任务ID（NULL=主任务，有值=分支任务）',
  `branch_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '分支状态：0=主任务，1=分支任务（部分出库）',
  `bom_item_id` bigint(20) NULL DEFAULT NULL COMMENT '关联的BOM组件ID（BOM模式使用，mes_bom_item.id）',
  `type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '类型',
  `sort` int(10) NULL DEFAULT NULL COMMENT '排序',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '角色状态（1正常 2进行中 3已完成 0异常完工,4待检查8其他用户完成）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '000000' COMMENT '租户编号',
  `mustbe` int(10) NULL DEFAULT NULL COMMENT '是否关键工序',
  `enough` int(5) NULL DEFAULT 1 COMMENT '是否够量',
  `stocknum` int(11) NULL DEFAULT 0 COMMENT '需出库数量',
  `outstocknum` int(11) NULL DEFAULT 0 COMMENT '出库数量',
  `checknum` int(11) NULL DEFAULT 0 COMMENT '当前质检次数',
  `ischecknew` int(3) NULL DEFAULT 0 COMMENT '是否通过质检',
  `worktype` int(11) NULL DEFAULT 0 COMMENT '流转类型',
  `remark2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `procure` int(11) NULL DEFAULT 0 COMMENT '是否采购完成',
  `resu` int(11) NULL DEFAULT 0 COMMENT '结果确认',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_step_id`(`step_id`) USING BTREE,
  INDEX `idx_process_route_id`(`process_route_id`) USING BTREE,
  INDEX `idx_bom_item`(`bom_item_id`) USING BTREE,
  INDEX `idx_branch_id`(`branch_id`) USING BTREE COMMENT '分支任务查询索引',
  INDEX `idx_branch_status`(`branch_status`) USING BTREE COMMENT '分支状态查询索引'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of mes_task
-- ----------------------------

