-- ----------------------------
-- Table structure for mes_work
-- ----------------------------
DROP TABLE IF EXISTS `mes_work`;
CREATE TABLE `mes_work`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `sn` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '编码',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标题',
  `fromtype` int(3) NULL DEFAULT NULL COMMENT '来源类型',
  `pro_id` bigint(20) NOT NULL COMMENT '产品关联',
  `neednum` int(5) NULL DEFAULT 0 COMMENT '所需数量',
  `uncount` int(11) NULL DEFAULT NULL COMMENT '未完成数量',
  `turncount` int(11) NULL DEFAULT NULL COMMENT '流转数量',
  `currnum` int(5) NULL DEFAULT 0 COMMENT '当前数量',
  `isturn` int(11) NULL DEFAULT 0 COMMENT '是否流转（1为流转',
  `processcount` int(11) NULL DEFAULT 0 COMMENT '工艺数量',
  `checkcount` int(11) NULL DEFAULT 0 COMMENT '质检次数',
  `istop` int(5) NULL DEFAULT 0 COMMENT '是否加急',
  `endtime` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '需求日期',
  `currprocess` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '当前工序',
  `okprocess` int(11) NULL DEFAULT 0 COMMENT '完成工序',
  `orderid` bigint(20) NULL DEFAULT NULL COMMENT '关联订单号',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '角色状态（0正常 1停用）',
  `execution_mode` tinyint(1) NULL DEFAULT 0 COMMENT '执行模式（0=老模式基于MesProsetting，1=新模式基于BOM+工艺路线）',
  `bom_id` bigint(20) NULL DEFAULT NULL COMMENT '关联的BOM版本ID（新模式使用）',
  `process_route_id` bigint(20) NULL DEFAULT NULL COMMENT '关联的工艺路线ID（新模式使用）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark1` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '000000' COMMENT '租户编号',
  `ismrp` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否与库存比较',
  `wul` int(10) NULL DEFAULT 0 COMMENT '物料打印次数',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `id`(`id`) USING BTREE,
  INDEX `idx_execution_mode`(`execution_mode`) USING BTREE,
  INDEX `idx_bom_route`(`bom_id`, `process_route_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '生产派单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of mes_work
-- ----------------------------

