-- ----------------------------
-- Procedure structure for sp_expand_bom_57
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_expand_bom_57`;
delimiter ;;
CREATE PROCEDURE `sp_expand_bom_57`(IN p_item_id BIGINT)
BEGIN
  DECLARE v_bom_id BIGINT;
  DECLARE v_level  INT DEFAULT 1;

  /* 临时表：当前层 / 下一层 / 树明细 / 叶子累加 */
  CREATE TEMPORARY TABLE IF NOT EXISTS tmp_curr (
    parent_item_id BIGINT,
    item_id        BIGINT,
    qty_cum        DECIMAL(20,6),
    uom_id         BIGINT,
    lvl            INT
  ) ENGINE=Memory;

  CREATE TEMPORARY TABLE IF NOT EXISTS tmp_next LIKE tmp_curr;

  CREATE TEMPORARY TABLE IF NOT EXISTS tmp_tree (
    parent_item_id BIGINT,
    child_item_id  BIGINT,
    qty_edge       DECIMAL(20,6),
    uom_id         BIGINT,
    lvl            INT
  ) ENGINE=Memory;

  CREATE TEMPORARY TABLE IF NOT EXISTS tmp_leaf (
    item_id  BIGINT,
    qty_cum  DECIMAL(20,6),
    uom_id   BIGINT
  ) ENGINE=Memory;

  TRUNCATE TABLE tmp_curr;
  TRUNCATE TABLE tmp_next;
  TRUNCATE TABLE tmp_tree;
  TRUNCATE TABLE tmp_leaf;

  /* 选定 “当前有效”的 BOM 头 */
  SET v_bom_id = (
    SELECT b.id
    FROM mes_bom b
    WHERE b.item_id = p_item_id
      AND b.status  = 1
      AND (b.eff_start IS NULL OR b.eff_start <= CURRENT_DATE())
      AND (b.eff_end   IS NULL OR b.eff_end   >= CURRENT_DATE())
    ORDER BY b.version DESC, COALESCE(b.eff_start,'1900-01-01') DESC
    LIMIT 1
  );

  /* 如果没有找到 BOM 头，直接返回空结果 */
  IF v_bom_id IS NULL THEN
    SELECT 'NO BOM FOUND' AS msg;
  ELSE
    /* 初始化：顶层的直接子件作为第1层 */
    SELECT
      p_item_id,
      bi.child_item_id,
      bi.qty * (1 + IFNULL(bi.scrap_rate,0)),
      bi.uom_id,
      1
    FROM mes_bom_item bi
    WHERE bi.bom_id = v_bom_id;

    /* 保护：最多展开 20 层 */
    WHILE EXISTS (SELECT 1 FROM tmp_curr) AND v_level <= 20 DO

      /* 保存树明细 */
      SELECT c.parent_item_id, c.item_id, c.qty_cum, c.uom_id, c.lvl
      FROM tmp_curr c;

      /* 可继续展开的 */
      SELECT
        c.item_id,
        bi2.child_item_id,
        c.qty_cum * (bi2.qty * (1 + IFNULL(bi2.scrap_rate,0))),
        bi2.uom_id,
        c.lvl + 1
      FROM tmp_curr c
      JOIN mes_bom b2
        ON b2.item_id = c.item_id
       AND b2.status  = 1
       AND (b2.eff_start IS NULL OR b2.eff_start <= CURRENT_DATE())
       AND (b2.eff_end   IS NULL OR b2.eff_end   >= CURRENT_DATE())
      JOIN mes_bom_item bi2 ON bi2.bom_id = b2.id;

      /* 不能再展开的 → 视作叶子 */
      SELECT c.item_id, c.qty_cum, c.uom_id
      FROM tmp_curr c
      WHERE NOT EXISTS (
        SELECT 1
        FROM mes_bom b3
        WHERE b3.item_id = c.item_id
          AND b3.status  = 1
          AND (b3.eff_start IS NULL OR b3.eff_start <= CURRENT_DATE())
          AND (b3.eff_end   IS NULL OR b3.eff_end   >= CURRENT_DATE())
      );

      TRUNCATE TABLE tmp_curr;
      TRUNCATE TABLE tmp_next;

      SET v_level = v_level + 1;
    END WHILE;

    /* 结果集 1：树明细 */
    SELECT
      t.lvl,
      t.parent_item_id,
      p1.title AS parent_name,
      t.child_item_id,
      p2.title AS child_name,
      t.qty_edge,
      t.uom_id
    FROM tmp_tree t
    LEFT JOIN mes_product p1 ON p1.id = t.parent_item_id
    LEFT JOIN mes_product p2 ON p2.id = t.child_item_id
    ORDER BY t.lvl, t.parent_item_id, t.child_item_id;

    /* 结果集 2：叶子件汇总 */
    SELECT
      l.item_id,
      p.title AS item_name,
      l.uom_id,
      SUM(l.qty_cum) AS req_qty_per_1_root
    FROM tmp_leaf l
    LEFT JOIN mes_product p ON p.id = l.item_id
    GROUP BY l.item_id, p.title, l.uom_id
    ORDER BY l.item_id;
  END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for sp_inout
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_inout`;
delimiter ;;
CREATE PROCEDURE `sp_inout`(IN `p_product_id` BIGINT, 
    IN `p_quantity` INT, 
    IN `p_location_id` BIGINT, 
    IN `p_tenant_id` VARCHAR(20), 
    OUT `p_success` INT)
BEGIN
    -- 1. 声明变量
    DECLARE total_quantity INT DEFAULT 0;
    DECLARE remaining_quantity INT DEFAULT p_quantity;
    DECLARE current_quantity INT;
    DECLARE current_location_id BIGINT;
    DECLARE done INT DEFAULT 0;

    -- 2. 提前声明游标（注意，这里先定义空表结构用于游标）
    DECLARE cur CURSOR FOR 
        SELECT location_id, total_quantity
        FROM tmp_fifo_inventory
        ORDER BY first_time;

    -- 3. 声明异常处理器
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    -- 4. 创建临时表（之后才执行逻辑）
    DROP TEMPORARY TABLE IF EXISTS tmp_fifo_inventory;
    CREATE TEMPORARY TABLE tmp_fifo_inventory (
        location_id BIGINT,
        total_quantity INT,
        first_time DATETIME
    );

    -- 5. 插入 FIFO 排序库存记录
    SELECT location_id, SUM(quantity), MIN(create_time)
    FROM mes_inventory_ledger
    WHERE stockid = p_product_id AND tenant_id = p_tenant_id
    GROUP BY location_id
    HAVING SUM(quantity) > 0;

    -- 6. 总库存检查
    SELECT COALESCE(SUM(quantity), 0) INTO total_quantity
    FROM mes_inventory_ledger
    WHERE stockid = p_product_id AND tenant_id = p_tenant_id;

    IF total_quantity < p_quantity THEN
        SET p_success = 0;
    ELSE
        IF p_location_id IS NOT NULL THEN
            -- 指定库位逻辑
            SELECT COALESCE(SUM(quantity), 0) INTO total_quantity
            FROM mes_inventory_ledger
            WHERE stockid = p_product_id 
              AND location_id = p_location_id 
              AND tenant_id = p_tenant_id;

            IF total_quantity >= p_quantity THEN
                    stockid, location_id, quantity, 
                    operation, batch_no, create_time, tenant_id
                )
                VALUES (
                    p_product_id, p_location_id, -p_quantity, 
                    2, NULL, NOW(), p_tenant_id
                );
                SET p_success = 1;
            ELSE
                SET p_success = 0;
            END IF;
        ELSE
            -- 未指定库位时，按 FIFO 出库
            OPEN cur;
            read_loop: LOOP
                FETCH cur INTO current_location_id, current_quantity;
                IF done THEN
                    LEAVE read_loop;
                END IF;

                IF remaining_quantity <= 0 THEN
                    LEAVE read_loop;
                END IF;

                SET @deduct = LEAST(current_quantity, remaining_quantity);

                    stockid, location_id, quantity, 
                    operation, batch_no, create_time, tenant_id
                )
                VALUES (
                    p_product_id, current_location_id, -@deduct, 
                    2, NULL, NOW(), p_tenant_id
                );

                SET remaining_quantity = remaining_quantity - @deduct;
            END LOOP;
            CLOSE cur;

            IF remaining_quantity = 0 THEN
                SET p_success = 1;
            ELSE
                SET p_success = 0;
            END IF;
        END IF;
    END IF;

    DROP TEMPORARY TABLE IF EXISTS tmp_fifo_inventory;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
